            if (hostPort.includes(func_dec(186)) && !hostPort.includes(func_dec(677))) {
                return hostPort.split(func_dec(186))[0];
            } else if (hostPort.startsWith(func_dec(676)) && hostPort.includes(func_dec(677))) {
                return hostPort.split(func_dec(677))[0].replace(func_dec(676), "");
            }
            return hostPort;
