function getCustomRouting() {
    let cr = sysConfig.customRouting || "";
    let lines = cr.split(func_dec(625)).map(l => l.trim()).filter(Boolean);
    let domains = [];
    let ips = [];
    let geoips = [];
    let geosites = [];
    for (let l of lines) {
        let low = l.toLowerCase();
        if (low.startsWith(func_dec(799))) {
            geoips.push(l.substring(6).trim().toUpperCase());
        } else if (low.startsWith(func_dec(800))) {
            geosites.push(l.substring(8).trim().toLowerCase());
        } else if (l.match(/^[0-9\.\/:]+$/)) {
            ips.push(l);
        } else {
            domains.push(l);
        }
    }
    return { domains, ips, geoips, geosites };
}

